import re
def cell_styles(path):
    data=open(path, encoding='utf-8').read()
    out={}
    for m in re.finditer(r'<c r="([A-Z]+)(\d+)" s="(\d+)"', data):
        out[f'{m.group(1)}{m.group(2)}']=m.group(3)
